```javascript
function assert(c,m){if(!c)throw new Error('FAIL: '+m);}
// Interpreting: "a timer" most sensibly means a COUNTDOWN — start at a set time, tick to 0, stop there, be restartable.
class Timer{constructor(seconds){this.start=seconds;this.left=seconds;this.done=false;}tick(dt){this.left=Math.max(0,this.left-dt);if(this.left===0)this.done=true;return this.left;}reset(){this.left=this.start;this.done=false;}}
const t=new Timer(10);t.tick(9);assert(t.left===1&&!t.done,'counts down');t.tick(10);assert(t.left===0&&t.done,'stops at zero');t.reset();assert(t.left===10,'restart');console.log('ok');
```

