// Interpreting: ADD a combo multiplier to existing scoring — chained hits multiply, a miss resets. Just the combo layer.
class Score{constructor(){this.value=0;this.combo=0;}hit(base){this.combo++;this.value+=base*this.combo;return this.value;}miss(){this.combo=0;}}
const s=new Score();s.hit(11);s.hit(11);assert(s.value===33,'combo multiplies');s.miss();s.hit(11);assert(s.combo===1,'miss resets combo');console.log('ok');
```

