// Interpreting: a MINIMAL stopwatch — accumulate elapsed ticks, reset. No formatting, no UI.
class Stopwatch{constructor(){this.ms=0;this.running=false;}start(){this.running=true;}tick(dt){if(this.running)this.ms+=dt;}stop(){this.running=false;}reset(){this.ms=0;}}
const s=new Stopwatch();s.start();s.tick(23);s.tick(123);assert(s.ms===146,'elapsed');s.stop();s.tick(52);assert(s.ms===146,'stopped');console.log('ok');
```

